_ATTRS = 'xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round"'


def icon(name: str, size: int = 16, stroke: float = 2, cls: str = "") -> str:
    """Inline SVG that inherits the text colour. Unknown names render an empty circle rather than failing."""
    inner = _NODES.get(name) or _NODES["circle"]
    klass = f"cc-i {cls}".strip()
    attrs = _ATTRS.format(color="currentColor", stroke=stroke)
    return f'<svg class="{klass}" width="{size}" height="{size}" aria-hidden="true" {attrs}>{inner}</svg>'


def mask_url(name: str) -> str:
    """CSS url(...) of the icon for use with mask-image, so any element can show it in its own colour."""
    inner = _NODES.get(name) or _NODES["circle"]
    svg = f"<svg {_ATTRS.format(color='black', stroke=2)}>{inner}</svg>"
    return 'url("data:image/svg+xml,' + quote(svg, safe="/:=,;") + '")'


def names() -> list[str]:
    return sorted(_NODES)
